import { useState, useEffect } from "react";

const theme = {
  primary: "#9400D3",
  accent: "#ED80E9",
  lightPurple: "#D3D3FF",
  muted: "#D8BFD8",
  white: "#ffffff",
  dark: "#1a1a2e",
};

const HomeIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 9.5L12 3l9 6.5V20a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V9.5z" />
    <path d="M9 21V12h6v9" />
  </svg>
);
const SearchIcon = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="11" cy="11" r="8" /><line x1="21" y1="21" x2="16.65" y2="16.65" />
  </svg>
);
const CategoryIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <rect x="3" y="3" width="7" height="7" rx="1" fill={filled ? "currentColor" : "none"} />
    <rect x="14" y="3" width="7" height="7" rx="1" fill={filled ? "currentColor" : "none"} />
    <rect x="3" y="14" width="7" height="7" rx="1" fill={filled ? "currentColor" : "none"} />
    <rect x="14" y="14" width="7" height="7" rx="1" fill={filled ? "currentColor" : "none"} />
  </svg>
);
const WishlistIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
  </svg>
);
const ProfileIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
    <circle cx="12" cy="7" r="4" fill={filled ? "currentColor" : "none"} />
  </svg>
);
const BagIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z" />
    <line x1="3" y1="6" x2="21" y2="6" />
    <path d="M16 10a4 4 0 0 1-8 0" />
  </svg>
);

const navTabs = [
  { id: "home",     label: "Home",     Icon: HomeIcon },
  { id: "search",   label: "Search",   Icon: SearchIcon },
  { id: "category", label: "Category", Icon: CategoryIcon },
  { id: "wishlist", label: "Wishlist", Icon: WishlistIcon },
  { id: "bag",      label: "Bag",      Icon: BagIcon,    badge: 1 },
  { id: "profile",  label: "Profile",  Icon: ProfileIcon },
];

export default function BottomNav() {
  const [active, setActive] = useState("home");
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  /* ─────────────── MOBILE ─────────────── */
  if (isMobile) {
    return (
      <>
        <div style={{ height: 70 }} />
        <nav style={{
          position: "fixed", bottom: 0, left: 0, right: 0, height: 64,
          background: theme.white,
          borderTop: `1.5px solid ${theme.lightPurple}`,
          boxShadow: `0 -4px 20px rgba(148,0,211,0.12)`,
          display: "flex", alignItems: "center", justifyContent: "space-around",
          zIndex: 9999, fontFamily: "'Helvetica Neue', Arial, sans-serif", padding: "0 4px",
        }}>
          {navTabs.map(({ id, label, Icon, badge }) => {
            const isActive = active === id;
            return (
              <button key={id} onClick={() => setActive(id)} style={{
                background: "none", border: "none", cursor: "pointer",
                display: "flex", flexDirection: "column", alignItems: "center",
                justifyContent: "center", gap: 3, flex: 1, padding: "6px 0",
                position: "relative", color: isActive ? theme.primary : "#aaa",
                transition: "color 0.2s",
              }}>
                {/* top pill */}
                {isActive && (
                  <span style={{
                    position: "absolute", top: -1, left: "50%", transform: "translateX(-50%)",
                    width: 32, height: 3, borderRadius: "0 0 4px 4px",
                    background: `linear-gradient(90deg, ${theme.primary}, ${theme.accent})`,
                  }} />
                )}
                {/* icon bubble */}
                <span style={{
                  display: "flex", alignItems: "center", justifyContent: "center",
                  width: 36, height: 36, borderRadius: "50%", position: "relative",
                  background: isActive ? `${theme.lightPurple}66` : "transparent",
                  transition: "background 0.2s",
                }}>
                  <Icon filled={isActive} />
                  {badge && (
                    <span style={{
                      position: "absolute", top: 2, right: 2,
                      background: `linear-gradient(135deg, ${theme.primary}, ${theme.accent})`,
                      color: "#fff", fontSize: 9, fontWeight: 700,
                      width: 15, height: 15, borderRadius: "50%",
                      display: "flex", alignItems: "center", justifyContent: "center",
                    }}>{badge}</span>
                  )}
                </span>
                <span style={{
                  fontSize: 10, fontWeight: isActive ? 700 : 500,
                  letterSpacing: 0.3,
                  color: isActive ? theme.primary : "#aaa",
                }}>{label}</span>
              </button>
            );
          })}
        </nav>
      </>
    );
  }

  /* ─────────────── DESKTOP ─────────────── */
  return (
    <>
      <div style={{ height: 72 }} />
      <nav style={{
        position: "fixed", bottom: 0, left: 0, right: 0,
        background: theme.white,
        borderTop: `2px solid ${theme.lightPurple}`,
        boxShadow: `0 -4px 24px rgba(148,0,211,0.10)`,
        zIndex: 9999, fontFamily: "'Helvetica Neue', Arial, sans-serif",
      }}>
        <div style={{
          maxWidth: 1280, margin: "0 auto",
          display: "flex", alignItems: "center",
          justifyContent: "space-between",
          padding: "0 40px", height: 56,
        }}>

          {/* Left — quick links */}
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ fontSize: 12, color: theme.muted, marginRight: 8, fontWeight: 600 }}>QUICK LINKS:</span>
            {["New Arrivals", "Best Sellers", "Sale", "Gift Cards", "Store Locator"].map((link) => (
              <button key={link} style={{
                background: "none", border: `1px solid ${theme.lightPurple}`,
                borderRadius: 20, padding: "4px 14px", fontSize: 12,
                color: theme.dark, cursor: "pointer", fontWeight: 500,
                transition: "all 0.15s",
                fontFamily: "inherit",
              }}
              onMouseEnter={e => {
                e.currentTarget.style.background = theme.primary;
                e.currentTarget.style.color = "#fff";
                e.currentTarget.style.borderColor = theme.primary;
              }}
              onMouseLeave={e => {
                e.currentTarget.style.background = "none";
                e.currentTarget.style.color = theme.dark;
                e.currentTarget.style.borderColor = theme.lightPurple;
              }}
              >{link}</button>
            ))}
          </div>

          {/* Center — nav tabs */}
          <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
            {navTabs.map(({ id, label, Icon, badge }) => {
              const isActive = active === id;
              return (
                <button key={id} onClick={() => setActive(id)} style={{
                  background: isActive ? `${theme.lightPurple}55` : "none",
                  border: isActive ? `1.5px solid ${theme.lightPurple}` : "1.5px solid transparent",
                  borderRadius: 10, cursor: "pointer",
                  display: "flex", alignItems: "center", gap: 7,
                  padding: "7px 16px", position: "relative",
                  color: isActive ? theme.primary : "#888",
                  transition: "all 0.2s", fontFamily: "inherit",
                }}>
                  <span style={{ display: "flex", alignItems: "center", position: "relative" }}>
                    <Icon filled={isActive} />
                    {badge && (
                      <span style={{
                        position: "absolute", top: -5, right: -6,
                        background: `linear-gradient(135deg, ${theme.primary}, ${theme.accent})`,
                        color: "#fff", fontSize: 9, fontWeight: 700,
                        width: 15, height: 15, borderRadius: "50%",
                        display: "flex", alignItems: "center", justifyContent: "center",
                      }}>{badge}</span>
                    )}
                  </span>
                  <span style={{
                    fontSize: 13, fontWeight: isActive ? 700 : 500,
                    color: isActive ? theme.primary : "#888",
                  }}>{label}</span>
                  {/* bottom active bar */}
                  {isActive && (
                    <span style={{
                      position: "absolute", bottom: -1, left: "20%", right: "20%",
                      height: 2, borderRadius: 2,
                      background: `linear-gradient(90deg, ${theme.primary}, ${theme.accent})`,
                    }} />
                  )}
                </button>
              );
            })}
          </div>

          {/* Right — copyright */}
          <div style={{ fontSize: 12, color: theme.muted, fontWeight: 500 }}>
            © {new Date().getFullYear()} <span style={{ color: theme.primary, fontWeight: 700 }}>The Zuro</span>. All rights reserved.
          </div>

        </div>
      </nav>
    </>
  );
}
